<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import AppIcon from './AppIcon.vue'
const props=defineProps<{modelValue:string}>(),emit=defineEmits<{(e:'update:modelValue',value:string):void;(e:'validity',valid:boolean):void}>()
const rows=ref<{users:number;seconds:number;ramp_seconds:number}[]>([]),raw=ref(''),error=ref('');let last=''
function parse(value:string){try{const parsed=JSON.parse(value);if(!Array.isArray(parsed))throw new Error('阶段必须是数组');for(const row of parsed)if(!Number.isInteger(row.users)||row.users<1||row.users>100||!Number.isInteger(row.seconds)||row.seconds<1||row.seconds>1800||!Number.isInteger(row.ramp_seconds??0)||(row.ramp_seconds??0)<0||(row.ramp_seconds??0)>row.seconds)throw new Error('每阶段用户数为 1～100，时长为 1～1800 秒，增长时间不能超过时长');rows.value=parsed.map(row=>({...row,ramp_seconds:row.ramp_seconds??0}));error.value='';emit('validity',true);return true}catch(e){error.value=e instanceof SyntaxError?'阶段 JSON 格式不正确':(e as Error).message;emit('validity',false);return false}}
watch(()=>props.modelValue,value=>{if(value===last)return;raw.value=value;last=value;parse(value)},{immediate:true})
function update(){const value=JSON.stringify(rows.value,null,2);raw.value=value;last=value;emit('update:modelValue',value);parse(value)}
function importRaw(){last=raw.value;emit('update:modelValue',raw.value);parse(raw.value)}
function add(){rows.value.push({users:rows.value.at(-1)?.users||2,seconds:10,ramp_seconds:1});update()}
const total=computed(()=>rows.value.reduce((sum,row)=>sum+Number(row.seconds||0),0)),maxUsers=computed(()=>Math.max(1,...rows.value.map(row=>Number(row.users||1))))
const points=computed(()=>{let time=0;const points:string[]=['30,125'];for(const row of rows.value){const x=(t:number)=>30+t/Math.max(total.value,1)*570,y=125-Number(row.users)/maxUsers.value*90;points.push(x(time)+',125',x(time+Number(row.ramp_seconds||0))+','+y);time+=Number(row.seconds||0);points.push(x(time)+','+y,x(time)+',125')}return points.join(' ')})
</script>
<template><section class="load-stages"><div class="section-heading"><div><h3>负载阶段</h3><p class="form-hint">不添加阶段时使用固定负载；每阶段建立独立用户会话。</p></div><button class="button secondary" type="button" @click="add"><AppIcon name="plus" :size="16"/>添加阶段</button></div><div v-for="(row,index) in rows" :key="index" class="stage-row"><strong>{{index+1}}</strong><label class="field-label">用户数<input v-model.number="row.users" type="number" min="1" max="100" @input="update"/></label><label class="field-label">时长（秒）<input v-model.number="row.seconds" type="number" min="1" max="1800" @input="update"/></label><label class="field-label">增长（秒）<input v-model.number="row.ramp_seconds" type="number" min="0" :max="row.seconds" @input="update"/></label><button class="icon-button danger" type="button" :aria-label="'删除负载阶段 '+(index+1)" @click="rows.splice(index,1);update()"><AppIcon name="trash" :size="16"/></button></div><div v-if="rows.length&&!error" class="load-preview"><div class="section-heading"><strong>模拟用户数</strong><span>{{total}} 秒 · 峰值 {{maxUsers}} 用户</span></div><svg viewBox="0 0 630 160" role="img" aria-label="负载阶段预览"><path d="M30 20V125H600" stroke="#cbd2da" fill="none"/><polyline :points="points" fill="none" stroke="#28765c" stroke-width="2"/><text x="30" y="150">0 秒</text><text x="550" y="150">{{total}} 秒</text><text x="4" y="35">{{maxUsers}}</text></svg></div><p v-if="error" class="inline-error" role="alert">{{error}}</p><details class="advanced-section"><summary>高级：编辑阶段 JSON</summary><textarea v-model="raw" rows="5" spellcheck="false" aria-label="负载阶段 JSON" @input="importRaw"/></details></section></template>
